# Configuration
SECRET_KEY = os.urandom(32)
SESSION_TIMEOUT = 3600

# Thread-local storage for request context
_request_context = threading.local()

def get_db():
    conn = sqlite3.connect(':memory:')
    conn.row_factory = sqlite3.Row
