# Session store
sessions = {}

def create_session(user_id, username, role):
    token = hashlib.sha256(os.urandom(32)).hexdigest()
    sessions[token] = {
        'user_id': user_id,
        'username': username,
        'role': role,
        'created': time.time()
    }
    return token

def validate_session(token):
    if not token or token not in sessions:
        return None
    session = sessions[token]
    if time.time() - session['created'] > SESSION_TIMEOUT:
        del sessions[token]
        return None
    return session

# Permission classification hierarchy
CLASSIFICATION_LEVELS = {
    'public': 0,
    'internal': 1,
    'confidential': 2,
    'secret': 3
}

ROLE_CLEARANCE = {
    'viewer': 0,
    'analyst': 1,
    'manager': 2,
    'admin': 3
}

class AccessPolicy:
    """Determines document access based on user clearance and document classification."""

    def __init__(self):
        self._cache = {}

    def evaluate(self, user_context, document_classification, action='read'):
        """Evaluate access policy. Returns (allowed, reason)."""
        cache_key = f"{user_context.get('role')}:{document_classification}:{action}"

        if cache_key in self._cache:
            return self._cache[cache_key]

        user_clearance = ROLE_CLEARANCE.get(user_context.get('role'), 0)
        doc_level = CLASSIFICATION_LEVELS.get(document_classification, 99)

        if action == 'read':
            allowed = user_clearance >= doc_level
        elif action == 'write':
            allowed = user_clearance >= doc_level and user_clearance >= 2
        elif action == 'delete':
            allowed = user_clearance >= 3
        else:
            allowed = False

        reason = 'granted' if allowed else f'insufficient clearance ({user_clearance} < {doc_level})'
        result = (allowed, reason)
        self._cache[cache_key] = result
        return result

# Global policy instance
access_policy = AccessPolicy()

def build_user_context(session):
    """Build a user context dict from session data."""
    return {
        'user_id': session['user_id'],
        'username': session['username'],
        'role': session['role'],
        'timestamp': time.time()
    }

def check_document_access(session, doc_id, action, conn):
    """Check if user can access a document. Returns (allowed, doc, reason)."""
    doc = conn.execute("SELECT * FROM documents WHERE id = ?", (doc_id,)).fetchone()
    if not doc:
        return (False, None, 'not found')

    user_context = build_user_context(session)
    allowed, reason = access_policy.evaluate(user_context, doc['classification'], action)

    # Log access attempt
    conn.execute(
        "INSERT INTO audit_log (user_id, action, resource_id, timestamp) VALUES (?, ?, ?, ?)",
        (session['user_id'], f"{action}:{('granted' if allowed else 'denied')}", doc_id, time.time())
    )
    conn.commit()

    return (allowed, dict(doc), reason)

def handle_request(method, path, headers, body, conn):
    """Main request router."""

    if path == '/api/login' and method == 'POST':
        data = json.loads(body) if body else {}
        username = data.get('username', '')
        password = data.get('password', '')

        if not username or not password:
            return (400, {'error': 'missing credentials'})

        user = conn.execute("SELECT * FROM users WHERE username = ?", (username,)).fetchone()
        if not user:
            return (401, {'error': 'invalid credentials'})

        # Verify password
        computed_hash = hashlib.pbkdf2_hmac(
            'sha256', 
            password.encode('utf-8'), 
            bytes.fromhex(user['salt']), 
            100000
        ).hex()

        if not hmac.compare_digest(computed_hash, user['password_hash']):
            return (401, {'error': 'invalid credentials'})

        token = create_session(user['id'], user['username'], user['role'])
        return (200, {'token': token, 'role': user['role']})

    elif path == '/api/whoami' and method == 'GET':
        token = headers.get('Authorization', '').replace('Bearer ', '')
        session = validate_session(token)
        if not session:
            return (401, {'error': 'unauthorized'})
        ctx = build_user_context(session)
        return (200, {'user_id': ctx['user_id'], 'username': ctx['username'], 'role': ctx['role']})

    elif path.startswith('/api/documents/') and method == 'GET':
        token = headers.get('Authorization', '').replace('Bearer ', '')
        session = validate_session(token)
        if not session:
            return (401, {'error': 'unauthorized'})

        try:
            doc_id = int(path.split('/')[-1])
        except (ValueError, IndexError):
            return (400, {'error': 'invalid document id'})

        allowed, doc, reason = check_document_access(session, doc_id, 'read', conn)
        if not allowed:
            return (403, {'error': 'access denied', 'reason': reason})

        return (200, {'document': doc})

    elif path == '/api/documents' and method == 'GET':
        token = headers.get('Authorization', '').replace('Bearer ', '')
        session = validate_session(token)
        if not session:
            return (401, {'error': 'unauthorized'})

        user_context = build_user_context(session)
        user_clearance = ROLE_CLEARANCE.get(user_context.get('role'), 0)

        docs = conn.execute("SELECT id, title, classification FROM documents").fetchall()
        visible = []
        for doc in docs:
            doc_level = CLASSIFICATION_LEVELS.get(doc['classification'], 99)
            if user_clearance >= doc_level:
                visible.append(dict(doc))

        return (200, {'documents': visible})

    return (404, {'error': 'not found'})


